mapper.sql:
WHERE transfer_schedules.is_active = 1 AND transfer_schedules.is_close = 0

    AND transfer_schedules.title LIKE CONCAT('%', #{filter.searchText}, '%')


    AND transfer_schedules.created_by = #{userId}


    AND (
    (
    DATE(transfer_schedules.start_date) >= #{filter.dateFrom} AND DATE(transfer_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(transfer_schedules.start_date) <= #{filter.dateTo} AND DATE(transfer_schedules.end_date) >= #{filter.dateTo}
    ) OR (
    DATE(transfer_schedules.start_date) <= #{filter.dateFrom} AND DATE(transfer_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(transfer_schedules.start_date) <= #{filter.dateTo} AND DATE(transfer_schedules.end_date) <= #{filter.dateTo}
    ) OR (
    DATE(transfer_schedules.start_date) >= #{filter.dateFrom} AND DATE(transfer_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(transfer_schedules.start_date) <= #{filter.dateTo} AND DATE(transfer_schedules.end_date) <= #{filter.dateTo}
    ) OR (
    DATE(transfer_schedules.start_date) <= #{filter.dateFrom} AND DATE(transfer_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(transfer_schedules.start_date) <= #{filter.dateTo} AND DATE(transfer_schedules.end_date) >= #{filter.dateTo}
    )
    )

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        transfer_schedules.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.insert:
